  try {
    const res = await fetch(url, { signal: controller.signal, credentials: 'include' });
    if (!res.ok) {
      const error = new Error(`HTTP ${res.status}: ${res.statusText}`);
      error.status = res.status;
      throw error;
    }
    return res.json();
  } finally {
    clearTimeout(id);
  }
};

