/** Salary formatting: uses salary_currency and period from API data. Falls back to raw value if metadata missing. */
const formatSalary = (min, max, currency = 'INR', period = 'annual') => {
  if (min == null && max == null) return 'Not specified';
  const value = max || min;
  if (period === 'annual' && currency === 'INR') {
    return `₹${(value / 100000).toFixed(1)} LPA`;
  }
  return `${currency} ${value?.toLocaleString()}`;
};

