// Custom hook
function useArrayField(key, defaultItem) {
  const add = () => persist({ ...profile, [key]: [...(profile[key] || []), defaultItem] });
  const update = (index, patch) => {
    const arr = [...(profile[key] || [])];
    arr[index] = { ...arr[index], ...patch };
    persist({ ...profile, [key]: arr });
  };
  const remove = (index) => {
    const arr = [...(profile[key] || [])];
    arr.splice(index, 1);
    persist({ ...profile, [key]: arr.length ? arr : [defaultItem] });
  };
  return { add, update, remove };
}

